import json, urllib.request, urllib.error, urllib.parse, time, os, sys

TENANT='dc763d48-a1fe-4194-abd9-488ac87de294'
SUB='3497a984-368c-4285-87c4-c03a4036c89b'
CLIENT='04b07795-8ddb-461a-bbee-02f9e1bf7b46'
_tok={'v':None,'exp':0}

def _refresh():
    rt=open('/tmp/arm_refresh.txt').read().strip() if os.path.exists('/tmp/arm_refresh.txt') else \
       list(json.load(open('/home/agent/.azure/msal_token_cache.json'))['RefreshToken'].values())[0]['secret']
    data=urllib.parse.urlencode({'client_id':CLIENT,'grant_type':'refresh_token','refresh_token':rt,
        'scope':'https://management.azure.com/.default'}).encode()
    r=json.load(urllib.request.urlopen(urllib.request.Request(
        f'https://login.microsoftonline.com/{TENANT}/oauth2/v2.0/token',data=data)))
    if 'refresh_token' in r: open('/tmp/arm_refresh.txt','w').write(r['refresh_token'])
    _tok['v']=r['access_token']; _tok['exp']=time.time()+int(r.get('expires_in',3600))-300
    return _tok['v']

def token():
    if not _tok['v'] or time.time()>_tok['exp']: return _refresh()
    return _tok['v']

def req(method, path, body=None, api=None, raw=False):
    url = path if path.startswith('http') else 'https://management.azure.com'+path
    if api and 'api-version' not in url:
        url += ('&' if '?' in url else '?')+'api-version='+api
    data=json.dumps(body).encode() if body is not None else None
    r=urllib.request.Request(url, data=data, method=method)
    r.add_header('Authorization','Bearer '+token())
    r.add_header('Content-Type','application/json')
    try:
        with urllib.request.urlopen(r) as resp:
            txt=resp.read().decode()
            out=json.loads(txt) if txt.strip() else {}
            if raw: return resp.status, dict(resp.headers), out
            return out
    except urllib.error.HTTPError as e:
        txt=e.read().decode()
        if raw: return e.code, dict(e.headers), txt
        raise RuntimeError(f'HTTP {e.code} {method} {url}\n{txt[:2000]}')

def put(path, body, api): return req('PUT', path, body, api)
def get(path, api): return req('GET', path, None, api)
def post(path, body, api): return req('POST', path, body, api)

def wait_provisioning(path, api, timeout=1800, interval=15, label=''):
    t0=time.time()
    while True:
        try:
            r=get(path, api)
            st=(r.get('properties') or {}).get('provisioningState') or r.get('provisioningState')
            print(f'[{int(time.time()-t0)}s] {label} state={st}', flush=True)
            if st in ('Succeeded','Ready'): return r
            if st in ('Failed','Canceled'): raise RuntimeError(f'{label} failed: {json.dumps(r)[:1500]}')
        except RuntimeError as e:
            print('poll err:', str(e)[:300], flush=True)
        if time.time()-t0>timeout: raise RuntimeError(f'{label} timeout')
        time.sleep(interval)
